class Origin:
    def __init__(self, origin: Dict[str, Any]):
        if not origin:
            origin = {}
        self.id = origin.get("Id", "")
        self.domain_name = origin.get("DomainName", "")
        self.origin_path = origin.get("OriginPath", "")
        custom_headers = origin.get("CustomHeaders", {})
        if isinstance(custom_headers, dict):
            self.custom_headers = custom_headers.get("Items", []) or []
        else:
            self.custom_headers = []
        s3_config = origin.get("S3OriginConfig", {})
        if isinstance(s3_config, dict):
            self.s3_access_identity = s3_config.get("OriginAccessIdentity", "")
        else:
            self.s3_access_identity = ""
        self.custom_origin = None
        if "CustomOriginConfig" in origin:
            self.custom_origin = CustomOriginConfig(origin["CustomOriginConfig"])
        self.connection_attempts = origin.get("ConnectionAttempts", 3)
        self.connection_timeout = origin.get("ConnectionTimeout", 10)
        origin_shield = origin.get("OriginShield", {})
        if isinstance(origin_shield, dict):
            self.origin_shield = origin_shield
        else:
            self.origin_shield = {"Enabled": False}

class Origin:
    def __init__(self, origin: Dict[str, Any]):
        if not origin:
            origin = {}
        self.id = origin.get("Id", "")
        self.domain_name = origin.get("DomainName", "")
        self.origin_path = origin.get("OriginPath", "")
        self.s3_access_identity = ""
        self.custom_origin = None
        origin_shield = origin.get("OriginShield", {})
        if isinstance(origin_shield, dict):
            self.origin_shield = origin_shield
        else:
            self.origin_shield = {"Enabled": False}
        self.connection_attempts = origin.get("ConnectionAttempts", 3)
        self.connection_timeout = origin.get("ConnectionTimeout", 10)

        s3_config = origin.get("S3OriginConfig")
        if s3_config:
            # Very rough validation
            if not self.domain_name.endswith("amazonaws.com"):
                raise DomainNameNotAnS3Bucket
            if isinstance(s3_config, dict):
                self.s3_access_identity = s3_config.get("OriginAccessIdentity", "")

        custom_config = origin.get("CustomOriginConfig")
        if custom_config:
            self.custom_origin = CustomOriginConfig(custom_config)

class DistributionConfig:
    def __init__(self, config: Dict[str, Any]):
        if not config:
            config = {}
        self.config = config
        aliases = config.get("Aliases", {})
        if isinstance(aliases, dict):
            items = aliases.get("Items", {})
            if isinstance(items, dict):
                self.aliases = items.get("CNAME", [])
            else:
                self.aliases = items or []
        else:
            self.aliases = []
        if isinstance(self.aliases, str):
            self.aliases = [self.aliases]

        self.comment = config.get("Comment", "")
        default_cache = config.get("DefaultCacheBehavior", {})
        if isinstance(default_cache, dict):
            self.default_cache_behavior = DefaultCacheBehaviour(default_cache)
        else:
            self.default_cache_behavior = DefaultCacheBehaviour({})

        self.cache_behaviors: List[Any] = []
        cache_behaviors = config.get("CacheBehaviors", {})
        if isinstance(cache_behaviors, dict):
            items = cache_behaviors.get("Items", {})
            if isinstance(items, dict):
                for _, v in items.items():
                    if isinstance(v, dict):
                        self.cache_behaviors.append(CacheBehaviour(v))

        self.custom_error_responses: List[Any] = []
        self.logging = Logging(config.get("Logging") or {})
        self.enabled = config.get("Enabled", False)
        self.viewer_certificate = ViewerCertificate()
        self.geo_restriction = GeoRestrictions(config.get("Restrictions") or {})
        self.caller_reference = config.get("CallerReference", str(random.uuid4()))

        origins = config.get("Origins", {})
        if isinstance(origins, dict):
            items = origins.get("Items", {})
            if isinstance(items, dict):
                self.origins = items.get("Origin", [])
            else:
                self.origins = items or []
        else:
            self.origins = []
        if not isinstance(self.origins, list):
            self.origins = [self.origins]

        # This check happens before any other Origins-validation
        if self.origins and self.default_cache_behavior.target_origin_id not in [
            o.get("Id") for o in self.origins if isinstance(o, dict)
        ]:
            raise OriginDoesNotExist

        self.origins = [Origin(o) for o in self.origins]
        self.price_class = config.get("PriceClass", "PriceClass_All")
        self.http_version = config.get("HttpVersion", "http2")
        is_ipv6 = config.get("IsIPV6Enabled", "true")
        if isinstance(is_ipv6, bool):
            self.is_ipv6_enabled = is_ipv6
        else:
            self.is_ipv6_enabled = str(is_ipv6).lower() == "true"
        self.default_root_object = config.get("DefaultRootObject", "")
        self.web_acl_id = config.get("WebACLId", "")
